// Process Slack Event WITH DEDUPLICATION
const body = $input.item.json.body;

// URL verification
if (body.type === 'url_verification') {
  return [{
    json: { challenge: body.challenge },
    pairedItem: { item: 0 }
  }];
}

// Event deduplication using event_id
const EVENT_CACHE_KEY = 'processed_slack_events_optimized';
const EVENT_CACHE_TTL = 300000; // 5 minutes in milliseconds

// Get or initialize event cache from workflow static data
let processedEvents = $getWorkflowStaticData('global')[EVENT_CACHE_KEY] || {};
const currentTime = Date.now();

// Clean expired entries (older than 5 minutes)
for (const [eventId, timestamp] of Object.entries(processedEvents)) {
  if (currentTime - timestamp > EVENT_CACHE_TTL) {
    delete processedEvents[eventId];
  }
}

// Handle app_mention events
if (body.type === 'event_callback' && body.event.type === 'app_mention') {
  const event = body.event;
  const eventId = body.event_id;

  // Check if this event was already processed (Slack retry detection)
  if (processedEvents[eventId]) {
    console.log(`⚠️ Duplicate event detected: ${eventId} (Slack retry #${processedEvents[eventId].retries || 1})`);
    // Update retry count for logging
    processedEvents[eventId].retries = (processedEvents[eventId].retries || 1) + 1;
    $getWorkflowStaticData('global')[EVENT_CACHE_KEY] = processedEvents;
    // Return empty to skip processing, but webhook still responds with 200 OK
    return [];
  }

  // Mark event as processed with timestamp
  processedEvents[eventId] = {
    timestamp: currentTime,
    retries: 0
  };
  $getWorkflowStaticData('global')[EVENT_CACHE_KEY] = processedEvents;

  const query = event.text.replace(/<@U09LPC5D2U8>/g, '').trim();

  return [{
    json: {
      query: query,
      channel: event.channel,
      user: event.user,
      thread_ts: event.ts,
      team_id: body.team_id,
      event_id: eventId
    },
    pairedItem: { item: 0 }
  }];
}

// Ignore other event types
return [];

// ===================================
// Slack Block Kit Formatter - Production Ready
// ===================================

// Get data from previous nodes
const agentOutput = $input.item.json;
const aiOutput = agentOutput.output || '';
const query = $('Process Event1').item.json.query || agentOutput.query || 'Your question';
const channel = $('Process Event1').item.json.channel || agentOutput.channel || 'C09KQT8EPGV';
const thread_ts = $('Process Event1').item.json.thread_ts || agentOutput.thread_ts;

// Note: Tool call logging (FR-034) should be implemented via a separate workflow node
// Cannot use require() in n8n Code nodes due to VM2 sandbox restrictions

// Citation validation check (improved regex to catch more patterns)
const hasCitations = /\[?BMS[\-\u2011][A-Z]+[\-\u2011][A-Z]+[\-\u2011]\d+\]?|https?:\/\/[^\s)]+|\[[\d,\s]+\]/.test(aiOutput);
const hasNoInfoStatement = /don't have information|not available in.*documentation|cannot find.*in.*database/i.test(aiOutput);

// Only warn if no citations AND not a "no info" response
let processedOutput = aiOutput;
if (!hasCitations && !hasNoInfoStatement && aiOutput.length > 50) {
  console.warn("⚠️ AI response lacks citations - possible hallucination");
  processedOutput = "⚠️ _Note: This response may not be fully grounded in documentation._\n\n" + aiOutput;
}

// Clean AI output - remove thinking artifacts
let cleanOutput = processedOutput
  .replace(/\[thinking\][\s\S]*?\[\/thinking\]/gi, '')
  .replace(/<thinking>[\s\S]*?<\/thinking>/gi, '')
  .replace(/^>.*$/gm, '')
  .replace(/={2,}/g, '')
  .trim();

// Extract document references
const docMatches = cleanOutput.match(/\[?BMS[\-\u2011][A-Z]+[\-\u2011][A-Z]+[\-\u2011]\d+[^\s)\]]*/g) || [];
const urlMatches = cleanOutput.match(/https?:\/\/[^\s)]+/g) || [];

// Split content into manageable sections (Slack has 3000 char limit per block)
const sections = cleanOutput.split('\n\n').filter(s => s.trim());
const mainContent = sections[0] || cleanOutput;

// Build Slack blocks
const blocks = [];

// Header with emoji
blocks.push({
  "type": "header",
  "text": {
    "type": "plain_text",
    "text": "🤖 Nomi BMS Assistant (Optimized)",
    "emoji": true
  }
});

// User's question
blocks.push({
  "type": "section",
  "text": {
    "type": "mrkdwn",
    "text": `*Your question:*\n> ${query}`
  }
});

blocks.push({"type": "divider"});

// Main answer (truncate if too long for Slack)
const truncatedContent = mainContent.length > 2900 
  ? mainContent.substring(0, 2900) + "...\n\n_[Response truncated - see full context in thread]_"
  : mainContent;

blocks.push({
  "type": "section",
  "text": {
    "type": "mrkdwn",
    "text": truncatedContent
  }
});

// Additional sections (max 3 more to avoid Slack limits)
for (let i = 1; i < Math.min(sections.length, 4); i++) {
  const section = sections[i];
  if (section.length > 0 && section.length < 2900) {
    blocks.push({
      "type": "section",
      "text": {
        "type": "mrkdwn",
        "text": section
      }
    });
  }
}

// Document references section (if any found)
if (docMatches.length > 0) {
  blocks.push({"type": "divider"});

  // Create unique document-URL pairs
  const docLinks = new Map();
  docMatches.forEach(doc => {
    const cleanDoc = doc.replace(/[.,;:!?)]$/, '');
    const matchingUrl = urlMatches.find(url => url.includes(cleanDoc));
    if (!docLinks.has(cleanDoc)) {
      docLinks.set(cleanDoc, matchingUrl);
    }
  });

  if (docLinks.size > 0) {
    let refsText = "*📚 Referenced Documents:*\n";
    let count = 0;
    docLinks.forEach((url, doc) => {
      if (count < 10) { // Limit to 10 refs to avoid spam
        if (url) {
          refsText += `• <${url}|${doc}>\n`;
        } else {
          refsText += `• \`${doc}\`\n`;
        }
        count++;
      }
    });

    if (docLinks.size > 10) {
      refsText += `\n_...and ${docLinks.size - 10} more documents_`;
    }

    blocks.push({
      "type": "section",
      "text": {
        "type": "mrkdwn",
        "text": refsText.trim()
      }
    });
  }
}

// Footer with timestamp
blocks.push({
  "type": "context",
  "elements": [{
    "type": "mrkdwn",
    "text": `⚡ Response generated at ${new Date().toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' })}`
  }]
});

// Return formatted response
return {
  json: {
    channel: channel,
    blocks: blocks,
    text: `${query.substring(0, 50)}...\n${mainContent.substring(0, 100)}...`,  // Fallback for notifications
    thread_ts: thread_ts  // Reply in thread if exists
  }
};
